"""
Karen's Ear — Embedding Semantic Evaluation Benchmark.

Curated pairs of emergency dispatches for behavioral verification of semantic embeddings
generated by sentence-transformers/all-MiniLM-L6-v2.

IMPORTANT EVALUATION NOTICE:
This benchmark evaluates the behavioral sanity of semantic vectors:
- Unit L2 norm invariance (||v||₂ ≈ 1.0)
- Self-similarity identity (u · u ≈ 1.0)
- Symmetry (sim(a, b) == sim(b, a))
- Relative semantic separation (related pairs > unrelated pairs)
- Adversarial sensitivity (negation and state changes alter vector representations)

It is NOT a supervised ground-truth incident deduplication benchmark.
It does NOT define backend incident fusion or duplicate thresholds.
"""

from __future__ import annotations

from dataclasses import dataclass


@dataclass(frozen=True)
class SemanticPair:
    """A pair of emergency dispatches with expected relative semantic relationship."""

    pair_id: str
    text_a: str
    text_b: str
    category: str  # "high_similarity", "lower_similarity", "adversarial_negation", "adversarial_state"
    domain: str    # "fire", "structural", "flood", "hazmat", "storm", "cross_domain"
    description: str


